pub fn stringCompareForJavaScript(comptime T: type, a: []const T, b: []const T) std.math.Order {
            const a_slice = a[0..@min(a.len, b.len)];
            const b_slice = b[0..@min(a.len, b.len)];
            var i: usize = 0;
            _ = &i;
            while (((i < a_slice.len) and (i < b_slice.len))) : (i = (i + 1)) {
                const a_char = a_slice[@as(usize, @intCast(i))];
                const b_char = b_slice[@as(usize, @intCast(i))];
                const delta: i32 = ((if (comptime @typeInfo(@TypeOf(a_char)) == .@"enum") cp_cast_int(i32, @intFromEnum(a_char)) else cp_cast_int(i32, a_char)) - (if (comptime @typeInfo(@TypeOf(b_char)) == .@"enum") cp_cast_int(i32, @intFromEnum(b_char)) else cp_cast_int(i32, b_char)));
                if ((delta != 0)) {
                    return (if ((delta < 0)) .lt else .gt);
                }
            }
            return std.math.order(a.len, b.len);
    }

pub inline fn order(self: String, other: *const String) std.math.Order {
            _ = bun.debugAssert((self.isUTF8() == other.isUTF8()));
            if (self.isUTF8()) {
                return String.stringCompareForJavaScript(u8, self.data, other.data);
            } else {
                return String.stringCompareForJavaScript(u16, self.slice16(), other.slice16());
            }
    }

pub fn clone(self: String, allocator: std.mem.Allocator) !String {
            return String{ .data = try allocator.dupe(u8, self.data), .prefer_template = self.prefer_template, .is_utf16 = (!self.isUTF8()) };
    }

pub fn cloneSliceIfNecessary(self: *const String, allocator: std.mem.Allocator) ![]const u8 {
            if (self.isUTF8()) {
                return allocator.dupe(u8, ((self.string(allocator)) catch unreachable));
            }
            return self.string(allocator);
    }

pub fn javascriptLength(self: String) ?u32 {
            if ((self.rope_len > 0)) {
                return self.rope_len;
            }
            if (self.isUTF8()) {
                if ((!strings.isAllASCII(self.data))) {
                    return null;
                }
                return @truncate(self.data.len);
            }
            return @truncate(self.slice16().len);
    }

pub inline fn len(self: String) usize {
            return (if ((self.rope_len > 0)) self.rope_len else self.data.len);
    }

pub inline fn isUTF8(self: String) bool {
            return (!self.is_utf16);
    }

pub inline fn isBlank(self: String) bool {
            return (self.len() == 0);
    }

pub inline fn isPresent(self: String) bool {
            return (self.len() > 0);
    }

pub fn eql(self: String, comptime _t: type, other: anytype) bool {
            if (self.isUTF8()) {
                if (_t == @This()) {
if (other.isUTF8()) {
                    return strings.eqlLong(self.data, other.data, true);
                } else {
                    return strings.utf16EqlString(other.slice16(), self.data);
                }
} else if (_t == []const u8) {
return strings.eqlLong(self.data, other, true);
} else if ((_t == []u16) or (_t == []const u16)) {
return strings.utf16EqlString(other, self.data);
} else {
_ = @compileError("Invalid type");
}
            } else {
                if (_t == @This()) {
if (other.isUTF8()) {
                    return strings.utf16EqlString(self.slice16(), other.data);
                } else {
                    return std.mem.eql(u16, other.slice16(), self.slice16());
                }
} else if (_t == []const u8) {
return strings.utf16EqlString(self.slice16(), other);
} else if ((_t == []u16) or (_t == []const u16)) {
return std.mem.eql(u16, other.slice16(), self.slice16());
} else {
_ = @compileError("Invalid type");
}
            }
    }

pub fn eqlComptime(self: String, comptime value: []const u8) bool {
            if ((!self.isUTF8())) {
                _ = bun.assertf((self.next == null), "transpiler: utf-16 string is a rope", .{});
                return strings.eqlComptimeUTF16(self.slice16(), value);
            }
            if ((self.next == null)) {
                return strings.eqlComptime(self.data, value);
            }
            return self.eql8Rope(value);
    }

pub fn eql8Rope(self: String, value: []const u8) bool {
            _ = bun.assertf(((self.next != null) and self.isUTF8()), "transpiler: bad call to eql8Rope", .{});
            if ((self.rope_len != value.len)) {
                return false;
            }
            var i: usize = 0;
            _ = &i;
            var next: ?*const String = (&self);
            _ = &next;
            while (next) |current| : (next = current.next) {
                if ((!strings.eqlLong(current.data, value[i..][0..current.data.len], false))) {
                    return false;
                }
                i = (i + current.data.len);
            }
            _ = bun.assertf((i == value.len), "transpiler: rope string length mismatch 1", .{});
            _ = bun.assertf((i == self.rope_len), "transpiler: rope string length mismatch 2", .{});
            return true;
    }

pub fn hasPrefixComptime(self: String, comptime value: anytype) bool {
            if ((self.data.len < value.len)) {
                return false;
            }
            return (if (self.isUTF8()) strings.eqlComptime(self.data[0..value.len], value) else strings.eqlComptimeUTF16(self.slice16()[0..value.len], value));
    }

pub fn string(self: *const String, allocator: std.mem.Allocator) OOM![]const u8 {
            if (self.isUTF8()) {
                return self.data;
            } else {
                return strings.toUTF8Alloc(allocator, self.slice16());
            }
    }

pub fn stringZ(self: *const String, allocator: std.mem.Allocator) OOM![:0]const u8 {
            if (self.isUTF8()) {
                return allocator.dupeZ(u8, self.data);
            } else {
                return strings.toUTF8AllocZ(allocator, self.slice16());
            }
    }

pub fn stringCloned(self: *const String, allocator: std.mem.Allocator) OOM![]const u8 {
            if (self.isUTF8()) {
                return allocator.dupe(u8, self.data);
            } else {
                return strings.toUTF8Alloc(allocator, self.slice16());
            }
    }

pub fn hash(self: String) u64 {
            if (self.isBlank()) {
                return 0;
            }
            if (self.isUTF8()) {
                return bun.hash(self.data);
            } else {
                return bun.hash((blk: {
                break :blk @as([*]const u8, @ptrCast(@alignCast(self.slice16().ptr)))[0..(self.slice16().len * 2)];

}));
            }
    }

pub fn toZigString(self: *String, allocator: std.mem.Allocator) jsc.ZigString {
            if (self.isUTF8()) {
                return jsc.ZigString.fromUTF8(cp_iter_slice(self)[@intCast(allocator)..]);
            } else {
                return jsc.ZigString.initUTF16(self.slice16());
            }
    }

pub fn format(s: String, writer: *std.Io.Writer) !void {
            _ = try writer.writeAll("E.String");
            if ((s.next == null)) {
                _ = try writer.writeAll("(");
                if (s.isUTF8()) {
                    _ = try writer.print("\"{s}\"", .{ s.data });
                } else {
                    _ = try writer.print("\"{f}\"", .{ bun.fmt.utf16(s.slice16()) });
                }
                _ = try writer.writeAll(")");
            } else {
                _ = try writer.writeAll("(rope: [");
                var it: ?*const String = (&s);
                _ = &it;
                while (it) |part| {
                    if (part.isUTF8()) {
                        _ = try writer.print("\"{s}\"", .{ part.data });
                    } else {
                        _ = try writer.print("\"{f}\"", .{ bun.fmt.utf16(part.slice16()) });
                    }
                    it = part.next;
                    if ((it != null)) {
                        _ = try writer.writeAll(" ");
                    }
                }
                _ = try writer.writeAll("])");
            }
    }

pub fn jsonStringify(self: String, writer: anytype) !void {
            var buf: [4096]u8 = undefined;
            _ = &buf;
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(self.slice16())) |char| {
                _ = &char;
                buf[cp_cast_int(usize, i)] = @as(u8, @truncate(char));
                i = (i + 1);
                if ((i >= 4096)) {
                    break;
                }
            }
            return try writer.write(buf[0..i]);
    }
