pub const TemplatePart = struct {
    value: ExprNodeIndex,
    tail_loc: logger.Loc,
    tail: Template.Contents,
};

pub const TemplateContents = union(TemplateContentsTag) {
    cooked: E.String,
    raw: []const u8,

pub fn isUTF8(self: TemplateContents) bool {
            return ((self == .cooked) and self.cooked.isUTF8());
    }
    const Tag = TemplateContentsTag;
};

pub const Template = struct {
    tag: ?ExprNodeIndex = null,
    parts: []TemplatePart = &.{},
    head: Contents,

pub fn fold(self: *Template, allocator: std.mem.Allocator, loc: logger.Loc) Expr {
            if (((self.tag != null) or ((self.head == .cooked) and (!self.head.cooked.isUTF8())))) {
                return Expr{ .data = .{ .e_template = self }, .loc = loc };
            }
            _ = bun.assert((self.head == .cooked));
            if ((self.parts.len == 0)) {
                return Expr.init(E.String, self.head.cooked, loc);
            }
            var parts = ((std.array_list.Managed(TemplatePart).initCapacity(allocator, self.parts.len)) catch unreachable);
            _ = &parts;
            var head = Expr.init(E.String, self.head.cooked, loc);
            _ = &head;
            for (cp_iter_slice(self.parts)) |part_src| {
                _ = &part_src;
                var part = part_src;
                _ = &part;
                _ = bun.assert((part.tail == .cooked));
                part.value = part.value.unwrapInlined();
                switch (part.value.data) {
.e_number => {
if (part.value.data.e_number.toString(allocator)) |s| {
                    _ = &s;
                    part.value = Expr.init(E.String, E.String.init(s), part.value.loc);
                }
},
.e_null => {
part.value = Expr.init(E.String, E.String.init("null"), part.value.loc);
},
.e_boolean => {
part.value = Expr.init(E.String, E.String.init((if ((if (@typeInfo(@TypeOf(part.value.data.e_boolean)) == .@"enum") @intFromEnum(part.value.data.e_boolean) else part.value.data.e_boolean.value)) "true" else "false")), part.value.loc);
},
.e_undefined => {
part.value = Expr.init(E.String, E.String.init("undefined"), part.value.loc);
},
.e_big_int => |value| {
part.value = Expr.init(E.String, E.String.init((if (@typeInfo(@TypeOf(value)) == .@"enum") @intFromEnum(value) else value.value)), part.value.loc);
},
else => {

},
}
                if ((((part.value.data == .e_string) and part.tail.cooked.isUTF8()) and part.value.data.e_string.isUTF8())) {
                    if ((parts.items.len == 0)) {
                        if ((part.value.data.e_string.len() > 0)) {
                            _ = head.data.e_string.push(Expr.init(E.String, part.value.data.e_string.*, logger.Loc.Empty).data.e_string);
                        }
                        if ((part.tail.cooked.len() > 0)) {
                            _ = head.data.e_string.push(Expr.init(E.String, part.tail.cooked, part.tail_loc).data.e_string);
                        }
                        continue;
                    } else {
                        var prev_part = (&parts.items[@as(usize, @intCast((parts.items.len - 1)))]);
                        _ = &prev_part;
                        _ = bun.assert((prev_part.tail == .cooked));
                        if (prev_part.tail.cooked.isUTF8()) {
                            if ((part.value.data.e_string.len() > 0)) {
                                _ = prev_part.tail.cooked.push(Expr.init(E.String, part.value.data.e_string.*, logger.Loc.Empty).data.e_string);
                            }
                            if ((part.tail.cooked.len() > 0)) {
                                _ = prev_part.tail.cooked.push(Expr.init(E.String, part.tail.cooked, part.tail_loc).data.e_string);
                            }
                        } else {
                            _ = parts.appendAssumeCapacity(part);
                        }
                    }
                } else {
                    _ = parts.appendAssumeCapacity(part);
                }
            }
            if ((parts.items.len == 0)) {
                _ = parts.deinit();
                _ = head.data.e_string.resolveRopeIfNeeded(allocator);
                return head;
            }
            return Expr.init(E.Template, .{ .tag = null, .parts = parts.items, .head = .{ .cooked = head.data.e_string.* } }, loc);
    }
    pub const Contents = TemplateContents;
};

pub const RegExp = struct {
    value: []const u8,
    flags_offset: ?u16 = null,

pub fn pattern(self: *const RegExp) []const u8 {
            if (self.flags_offset) |i_| {
                _ = &i_;
                var i = i_;
                _ = &i;
                while (((i > 0) and (self.value[@as(usize, @intCast(i))] != 47))) {
                    i = (i - 1);
                }
                return std.mem.trim(u8, self.value[0..i], "/");
            }
            return std.mem.trim(u8, self.value, "/");
    }

pub fn flags(self: *const RegExp) []const u8 {
            if (self.flags_offset) |i| {
                _ = &i;
                return self.value[i..];
            }
            return "";
    }

pub fn jsonStringify(self: RegExp, writer: anytype) !void {
            return try writer.write(self.value);
    }
    pub const empty: RegExp = RegExp{ .value = "" };
