pub fn isImportRecordNull(self: Import) bool {
            return (self.import_record_index == std.math.maxInt(u32));
    }

pub fn importRecordLoader(imp: *const Import) ?bun.options.Loader {
            const obj_expr = imp.options.data.@"as"(.e_object);
            if ((obj_expr == null)) {
                return null;
            }
            const obj = obj_expr.?;
            var with = obj.get("with");
            _ = &with;
            if ((with == null)) {
                with = obj.get("assert");
            }
            if ((with == null)) {
                return null;
            }
            const with_obj_expr = with.?.data.@"as"(.e_object);
            if ((with_obj_expr == null)) {
                return null;
            }
            const with_obj = with_obj_expr.?;
            const type_val = with_obj.get("type");
            if ((type_val == null)) {
                return null;
            }
            const str_expr = type_val.?.data.@"as"(.e_string);
            if ((str_expr == null)) {
                return null;
            }
            const str = str_expr.?;
            if ((!str.is_utf16)) {
                if (bun.options.Loader.fromString(str.data)) |loader| {
                    _ = &loader;
                    if ((loader == .sqlite)) {
                        const embed = with_obj.get("embed");
                        if ((embed == null)) {
                            return loader;
                        }
                        const embed_str = embed.?.data.@"as"(.e_string);
                        if ((embed_str == null)) {
                            return loader;
                        }
                        if (embed_str.?.eqlComptime("true")) {
                            return .sqlite_embedded;
                        }
                    }
                    return loader;
                }
            }
            return null;
    }
};

